#!/bin/bash
# Fetches the self-contained build toolchain into ./toolchain.
# Reproduces exactly the versions the app was built with. macOS only.
# Components (debug.keystore is auto-generated by build.sh, not fetched):
#   jdk-17.0.13+11/   Temurin (Adoptium) JDK 17.0.13+11   (arch-specific)
#   android-14/       Android build-tools 34.0.0          (aapt2, d8, zipalign, apksigner)
#   android-13/       Android platform 33 rev 2           (android.jar)
#   platform-tools/   platform-tools 37.0.0               (adb)
#
# Android SDK components are covered by the Android SDK Terms and Conditions
# (https://developer.android.com/studio/terms). Running this script downloads them.
set -euo pipefail

DIR="$(cd "$(dirname "$0")" && pwd)"
TC="$DIR/toolchain"

[ "$(uname -s)" = "Darwin" ] || { echo "ERROR: this toolchain is macOS-only." >&2; exit 1; }
case "$(uname -m)" in
  arm64)  JARCH=aarch64 ;;
  x86_64) JARCH=x64 ;;
  *) echo "ERROR: unsupported arch $(uname -m)" >&2; exit 1 ;;
esac

JDK_TARBALL="OpenJDK17U-jdk_${JARCH}_mac_hotspot_17.0.13_11.tar.gz"
JDK_URL="https://github.com/adoptium/temurin17-binaries/releases/download/jdk-17.0.13%2B11/${JDK_TARBALL}"
BUILDTOOLS_URL="https://dl.google.com/android/repository/build-tools_r34-macosx.zip"
PLATFORM_URL="https://dl.google.com/android/repository/platform-33_r02.zip"
PLATFORMTOOLS_URL="https://dl.google.com/android/repository/platform-tools_r37.0.0-darwin.zip"

mkdir -p "$TC"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT

# fetch_zip <url> <marker-path-relative-to-TC>
fetch_zip() {
  local url="$1" marker="$2" name; name="$(basename "$url")"
  if [ -e "$TC/$marker" ]; then echo "[skip] $marker already present"; return; fi
  echo "[get ] $name"
  curl -fL --retry 3 -o "$TMP/$name" "$url"
  echo "[unzip] $name -> toolchain/"
  unzip -q -o "$TMP/$name" -d "$TC"
  [ -e "$TC/$marker" ] || { echo "ERROR: expected $marker after unzip of $name" >&2; exit 1; }
  rm -f "$TMP/$name"
}

# JDK (tarball, arch-specific)
if [ -x "$TC/jdk-17.0.13+11/Contents/Home/bin/java" ]; then
  echo "[skip] jdk-17.0.13+11 already present"
else
  echo "[get ] $JDK_TARBALL"
  curl -fL --retry 3 -o "$TMP/$JDK_TARBALL" "$JDK_URL"
  echo "[untar] $JDK_TARBALL -> toolchain/"
  tar -xzf "$TMP/$JDK_TARBALL" -C "$TC"
  [ -x "$TC/jdk-17.0.13+11/Contents/Home/bin/java" ] \
    || { echo "ERROR: JDK not where expected after untar" >&2; exit 1; }
  rm -f "$TMP/$JDK_TARBALL"
fi

fetch_zip "$BUILDTOOLS_URL"     "android-14/aapt2"
fetch_zip "$PLATFORM_URL"       "android-13/android.jar"
fetch_zip "$PLATFORMTOOLS_URL"  "platform-tools/adb"

echo "OK: toolchain ready in $TC  (debug.keystore is created by build.sh on first sign)"
